"""Native style-driven motion titles and clip-boundary transitions."""
import math

TRANSITIONS = {"straight-cut", "soft-cut", "match-cut"}
INTENSITY = {"low": 0.18, "medium": 0.32, "high": 0.48}

def _escape(text):
    return str(text).replace("\\", "\\\\").replace(":", "\\:").replace("'", "\\'").replace("%", "\\%")

def motion_filters(clip, timeline):
    """Optional explicitly approved motion titles; no autogenerated factual overlays."""
    profile = timeline.get("style_profile") or {}
    style = dict(profile, **(clip.get("style") or {}))
    level = style.get("motion_intensity", "medium")
    if level not in INTENSITY:
        raise ValueError("Unknown motion intensity")
    filters = []
    for cue in clip.get("motion_graphics") or []:
        if cue.get("review_status") not in ("approved", "auto_approved"):
            continue
        if cue.get("type") != "title":
            raise ValueError("Only approved title cues supported by native motion adapter")
        text = str(cue.get("text", "")).strip()
        if not text or len(text) > 160:
            raise ValueError("Title must contain 1-160 characters")
        start, end = float(cue["start"]), float(cue["end"])
        if not math.isfinite(start) or not math.isfinite(end) or not 0 <= start < end <= float(clip["duration"]):
            raise ValueError("Invalid motion title timing")
        font = _escape(style.get("font_family", "Sans"))
        color = str((style.get("palette") or ["#FFFFFF"])[-1]).replace("#", "0x")
        if not (color.startswith("0x") and len(color) == 8 and all(x in "0123456789abcdefABCDEF" for x in color[2:])):
            raise ValueError("Invalid title color")
        margin = float(style.get("safe_margin_percent", 8)) / 100
        if not 0 <= margin <= .25:
            raise ValueError("Invalid title margin")
        position = style.get("caption_position", "top")
        if position not in ("top", "bottom"):
            raise ValueError("Unknown title position")
        y = f"h*{margin:.3f}" if position == "top" else f"h*(1-{margin:.3f})-text_h"
        fade = min(INTENSITY[level], (end-start)/2)
        opacity = (f"min(1,max(0,(t-{start:.3f})/{fade:.3f}),max(0,({end:.3f}-t)/{fade:.3f}))"
                   if fade else "1")
        filters.append(f"drawtext=text='{_escape(text)}':font='{font}':fontcolor={color}:"
                       f"fontsize=h/22:x=(w-text_w)/2:y={y}:alpha='{opacity}':"
                       f"enable='between(t,{start:.3f},{end:.3f})'")
    return filters

def transition_filters(clip, timeline):
    """Clip-edge dip-to-black for soft-cut; match-cut is intentionally a hard cut."""
    profile = timeline.get("style_profile") or {}
    style = dict(profile, **(clip.get("style") or {}))
    transition = style.get("transition", "straight-cut")
    if transition not in TRANSITIONS:
        raise ValueError("Unknown transition")
    if transition != "soft-cut":
        return []
    duration = float(clip["duration"])
    fade = min(.12, duration/4)
    if fade <= 0:
        return []
    return [f"fade=t=in:st=0:d={fade:.3f}", f"fade=t=out:st={duration-fade:.3f}:d={fade:.3f}"]
